use verus::prelude::*;

verus! {
    /// Construct an n×m matrix of f64 where entry (i,j) = 1.0 if j ≤ i + k, else 0.0.
    pub fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>>
        ensures |res: &Vec<Vec<f64>>|
            // The result has exactly n rows
            res.len() == n
            // For each row i < n, it has exactly m columns
            && forall(|i: usize| i < n
                ==>
                    res[i].len() == m
                    // And for each column j < m, the value is 1.0 iff j ≤ i + k
                    && forall(|j: usize| j < m
                        ==>
                            res[i][j] ==
                                if (j as int) <= (i as int + (k as int)) {
                                    1.0
                                } else {
                                    0.0
                                }
                    )
            )
    {
        let mut res: Vec<Vec<f64>> = Vec::new();
        let mut i: usize = 0;

        // Build rows one by one
        while i < n
            invariant     res.len() == i
            invariant     // all already‐built rows satisfy the specification
                forall(|ii: usize| ii < i
                    ==>
                        res[ii].len() == m
                        && forall(|jj: usize| jj < m
                            ==>
                                res[ii][jj] ==
                                    if (jj as int) <= (ii as int + (k as int)) {
                                        1.0
                                    } else {
                                        0.0
                                    }
                        )
                )
            decreases    n - i
        {
            let mut row: Vec<f64> = Vec::new();
            let mut j: usize = 0;

            // Build the i-th row element by element
            while j < m
                invariant     row.len() == j
                invariant     // all already‐filled columns in this row satisfy the spec
                    forall(|jj: usize| jj < j
                        ==>
                            row[jj] ==
                                if (jj as int) <= (i as int + (k as int)) {
                                    1.0
                                } else {
                                    0.0
                                }
                    )
                decreases    m - j
            {
                // Push 1.0 if j ≤ i + k, else 0.0
                if (j as i32) <= (i as i32 + k) {
                    row.push(1.0);
                } else {
                    row.push(0.0);
                }
                j += 1;
            }

            // Row is complete
            assert(row.len() == m);
            res.push(row);
            i += 1;
        }

        // All rows built
        assert(res.len() == n);
        res
    }
}